Below is a Vega-Lite spec that loads daily active users from the given JSON endpoint and plots a color-blind–safe blue line with axis titles and a tooltip.

```json
{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": "https://example.org/dau.json",
    "format": {
      "type": "json"
    }
  },
  "mark": {
    "type": "line",
    "color": "#0072B2",
    "strokeWidth": 2
  },
  "encoding": {
    "x": {
      "field": "date",
      "type": "temporal",
      "axis": {
        "title": "Date"
      }
    },
    "y": {
      "field": "users",
      "type": "quantitative",
      "axis": {
        "title": "Daily active users"
      }
    },
    "tooltip": [
      {
        "field": "date",
        "type": "temporal",
        "title": "Date"
      },
      {
        "field": "users",
        "type": "quantitative",
        "title": "Users"
      }
    ]
  },
  "width": 600,
  "height": 300
}
```

I added a window transform that computes a 7-day moving average (frame: [-6, 0]) and layered a second line (orange) showing that ma7 on the same axes; both lines include tooltips and use a color-blind-safe palette. 

```json
{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": "https://example.org/dau.json",
    "format": {
      "type": "json"
    }
  },
  "transform": [
    {
      "window": [
        {
          "op": "mean",
          "field": "users",
          "as": "ma7"
        }
      ],
      "frame": [
        -6,
        0
      ],
      "sort": [
        {
          "field": "date",
          "order": "ascending"
        }
      ]
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "line",
        "color": "#0072B2",
        "strokeWidth": 1.5
      },
      "encoding": {
        "x": {
          "field": "date",
          "type": "temporal",
          "axis": {
            "title": "Date"
          }
        },
        "y": {
          "field": "users",
          "type": "quantitative",
          "axis": {
            "title": "Daily active users"
          }
        },
        "tooltip": [
          {
            "field": "date",
            "type": "temporal",
            "title": "Date"
          },
          {
            "field": "users",
            "type": "quantitative",
            "title": "Users"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "line",
        "color": "#E69F00",
        "strokeWidth": 2.5
      },
      "encoding": {
        "x": {
          "field": "date",
          "type": "temporal"
        },
        "y": {
          "field": "ma7",
          "type": "quantitative"
        },
        "tooltip": [
          {
            "field": "date",
            "type": "temporal",
            "title": "Date"
          },
          {
            "field": "ma7",
            "type": "quantitative",
            "title": "7-day MA"
          }
        ]
      }
    }
  ],
  "width": 600,
  "height": 300
}
```

